#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, capacity;
    cin >> n >> capacity;
    vector<int> dp(capacity + 1, 0);
    for (int i = 0; i < n; ++i) {
        int weight, value;
        cin >> weight >> value;
        for (int w = capacity; w >= weight; --w)
            dp[w] = max(dp[w], dp[w - weight] + value);
    }
    cout << dp[capacity] << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    vector<int> tails;
    for (int value : a) {
        auto it = lower_bound(tails.begin(), tails.end(), value);
        if (it == tails.end()) tails.push_back(value);
        else *it = value;
    }
    cout << tails.size() << '\n';
    return 0;
}
